<template><section><div class="mb-6 flex items-center justify-between"><div><h1 class="text-2xl font-bold">{{t('admin.title')}}</h1></div><button class="btn-primary" @click="modal=true">+ {{t('admin.new')}}</button></div><div class="grid gap-4 lg:grid-cols-2"><div class="card"><h2 class="mb-4 font-semibold">{{t('admin.admins')}}</h2><div class="space-y-3"><div v-for="a in admins" :key="a.id" class="flex items-center justify-between rounded-xl bg-white/5 p-3"><div><div class="font-medium">{{a.username}}</div><div class="text-xs text-slate-500">{{a.role}} · {{a.last_login_at?new Date(a.last_login_at).toLocaleString():'never'}}</div></div><button v-if="a.id!==me" class="btn-danger" @click="remove(a.id)">{{t('common.delete')}}</button></div></div></div><div class="card"><h2 class="mb-4 font-semibold">{{t('admin.roles')}}</h2><div v-for="r in roles" :key="r.id" class="mb-3 rounded-xl bg-white/5 p-3"><div class="font-medium">{{r.name}}</div><div class="mt-1 text-xs text-slate-500">{{r.description}}</div><div class="mt-2 flex flex-wrap gap-1"><span v-for="p in perms(r.permissions)" :key="p" class="rounded-full bg-brand-500/10 px-2 py-1 text-[10px] text-brand-300">{{p}}</span></div></div></div></div><div v-if="modal" class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4"><form class="card w-full max-w-md space-y-3" @submit.prevent="create"><h2 class="text-lg font-semibold">{{t('admin.new')}}</h2><input v-model="form.username" class="input" :placeholder="t('admin.username')" required/><input v-model="form.password" class="input" type="password" minlength="10" :placeholder="t('admin.password')" required/><select v-model="form.role" class="input"><option v-for="r in roles" :key="r.name">{{r.name}}</option></select><div class="flex justify-end gap-2"><button type="button" class="btn-ghost" @click="modal=false">{{t('common.cancel')}}</button><button class="btn-primary">{{t('common.create')}}</button></div></form></div></section></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';import{useAuthStore}from'../stores/auth';const{t}=useI18n(),auth=useAuthStore(),admins=ref<any[]>([]),roles=ref<any[]>([]),modal=ref(false),me=ref<number>(0),form=ref({username:'',password:'',role:'viewer'});function perms(s:string){try{return JSON.parse(s)}catch{return[]}}async function load(){const [a,r,m]=await Promise.all([api.get<any>('/admin/admins'),api.get<any>('/admin/roles'),api.get<any>('/auth/me')]);admins.value=a.admins;roles.value=r.roles;me.value=m.admin.id}async function create(){await api.post('/admin/admins',form.value);modal.value=false;form.value={username:'',password:'',role:'viewer'};await load()}async function remove(id:number){if(confirm('Delete administrator?')){await api.delete(`/admin/admins/${id}`);await load()}}onMounted(load);</script>
